--
-- Name: backup_coverage; Type: TABLE; Schema: diskaudit; Owner: -
--

CREATE TABLE diskaudit.backup_coverage (
    host text NOT NULL,
    path text NOT NULL,
    size_bytes bigint,
    inode bigint,
    nlink integer,
    classification text NOT NULL,
    match_method text,
    excluded_rule_id bigint,
    matched_nas_host text,
    matched_nas_path text,
    matched_restic_target text,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    run_id bigint,
    notes text,
    restic_snapshot_id text,
    restic_verified_at timestamp with time zone,
    CONSTRAINT backup_coverage_classification_check CHECK ((classification = ANY (ARRAY['BACKED_UP_VERIFIED'::text, 'BACKED_UP_UNVERIFIED'::text, 'NOT_BACKED_UP'::text, 'EXCLUDED'::text]))),
    CONSTRAINT backup_coverage_match_method_check CHECK ((match_method = ANY (ARRAY['hash_proven'::text, 'path_size_mtime'::text, 'restic_snapshot_listing'::text, 'none'::text])))
);


--
-- Name: TABLE backup_coverage; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON TABLE diskaudit.backup_coverage IS 'Complete-universe answer to "what on the scanned hosts is NOT safely on the NAS" -- one row per in-scope file (EXCLUDED rows included, for auditability). Built by backup_coverage.py, NOT limited to critical_patterns (see v_backup_coverage) or the cross-host size-candidate set (see crosshost_verify.py) -- both of those cover <1% of the true file universe on the scanned hosts. BACKED_UP_VERIFIED = hash-proven bit-identical copy confirmed. BACKED_UP_UNVERIFIED = a plausible NAS/restic counterpart exists by path+size+mtime but has not (yet) been cryptographically confirmed -- never report this tier as proof. NOT_BACKED_UP = no counterpart found at all -- the actual deliverable list. EXCLUDED = matched a diskaudit.backup_scope_rules rule (see excluded_rule_id).';


--
-- Name: COLUMN backup_coverage.restic_snapshot_id; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON COLUMN diskaudit.backup_coverage.restic_snapshot_id IS 'restic snapshot id whose listing matched this file on path+size+mtime (set by backup coverage-sync)';


