    last_heartbeat_at timestamp with time zone,
    current_stage text,
    notes text,
    CONSTRAINT backup_coverage_runs_phase_check CHECK ((phase = ANY (ARRAY['classify'::text, 'verify'::text]))),
    CONSTRAINT backup_coverage_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text])))
);


