    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT backup_scope_rules_category_check CHECK ((category = ANY (ARRAY['excluded_os'::text, 'excluded_cache'::text, 'excluded_transient'::text, 'excluded_own_backup_staging'::text, 'excluded_other'::text])))
);


--
-- Name: TABLE backup_scope_rules; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON TABLE diskaudit.backup_scope_rules IS 'Auditable, editable exclusion rules for backup-coverage scoping. A file is EXCLUDED from the "needs backup" universe iff it matches an active rule here, with the exact rule + reason recorded on the resulting diskaudit.backup_coverage row -- so the operator can see and challenge every exclusion, not just trust a hardcoded list. Edit via SQL (INSERT/UPDATE active=false), never by editing backup_coverage.py''s source.';


