--
-- Name: mv_file_status; Type: MATERIALIZED VIEW; Schema: diskaudit; Owner: -
--

CREATE MATERIALIZED VIEW diskaudit.mv_file_status AS
 WITH threshold AS (
         SELECT diskaudit.classification_threshold_days() AS days
        ), flagged AS (
         SELECT f.host,
            f.path,
            f.file_type,
            f.size_bytes,
            f.owner_name,
            f.mtime,
            f.atime,
            f.duplicate_group_id,
            (f.atime < (now() - ((t.days || ' days'::text))::interval)) AS is_atime_old,
            (f.duplicate_group_id IS NOT NULL) AS is_duplicated,
            (EXISTS ( SELECT 1
                   FROM diskaudit.load_bearing_paths lbp
                  WHERE (f.path ~~ lbp.pattern))) AS is_load_bearing,
            (EXISTS ( SELECT 1
                   FROM diskaudit.decommissioned_path_patterns dpp
                  WHERE (f.path ~~ dpp.pattern))) AS is_decommissioned,
            (EXISTS ( SELECT 1
                   FROM diskaudit.critical_patterns cp
                  WHERE (f.path ~~ cp.pattern))) AS is_critical,
            ((f.path ~* '\.bak(-|\.|$)'::text) OR (f.path ~* '_old(\.[a-z0-9]+)?$'::text) OR (f.path ~* '_deprecated(\.[a-z0-9]+)?$'::text) OR (f.path ~~ '%.DEPRECATED-%'::text) OR (f.path ~* '_v[0-9]+_old'::text)) AS is_legacy_naming
           FROM (diskaudit.files f
             CROSS JOIN threshold t)
          WHERE (f.still_exists AND (f.file_type = 'regular'::text))
        )
 SELECT host,
    path,
    file_type,
    size_bytes,
    owner_name,
    mtime,
    atime,
    duplicate_group_id,
    is_legacy_naming,
        CASE
            WHEN is_load_bearing THEN 'load-bearing'::text
            WHEN is_decommissioned THEN 'orphaned-decommissioned-system'::text
            WHEN (is_atime_old AND is_critical) THEN 'critical-protected'::text
            WHEN (is_atime_old AND is_duplicated) THEN 'possibly-obsolete'::text
            WHEN is_atime_old THEN 'stale'::text
            ELSE 'active'::text
        END AS file_status,
    is_load_bearing,
    is_decommissioned,
    is_critical,
    is_duplicated,
    is_atime_old,
    now() AS computed_at
   FROM flagged
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_file_status; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON MATERIALIZED VIEW diskaudit.mv_file_status IS 'Classification of still-existing regular files by orphaned/stale/possibly-obsolete/load-bearing status. Refreshed by diskaudit.refresh_file_status() via diskaudit-classification-refresh.timer, NOT live. See the project runbook';


--
-- Name: mv_dedup_groups_by_host; Type: MATERIALIZED VIEW; Schema: diskaudit; Owner: -
--

CREATE MATERIALIZED VIEW diskaudit.mv_dedup_groups_by_host AS
 WITH members AS (
         SELECT f.duplicate_group_id,
            f.host,
            f.path,
            f.size_bytes,
            f.inode,
            f.mtime,
            f.content_sha256,
            f.dedup_tool,
            f.hash_source,
            COALESCE(mfs.is_load_bearing, false) AS is_load_bearing,
            COALESCE(mfs.is_decommissioned, false) AS is_decommissioned,
            (EXISTS ( SELECT 1
                   FROM diskaudit.critical_patterns cp
                  WHERE ((cp.category = 'os_system'::text) AND (f.path ~~ cp.pattern)))) AS is_os_system_critical,
            (EXISTS ( SELECT 1
                   FROM diskaudit.critical_patterns cp
                  WHERE ((cp.category = 'application'::text) AND (f.path ~~ cp.pattern)))) AS is_application_critical,
            (EXISTS ( SELECT 1
                   FROM diskaudit.file_category_patterns fcp
                  WHERE ((fcp.category = 'os_system'::text) AND (f.path ~~ fcp.pattern)))) AS is_os_system_extra,
            (EXISTS ( SELECT 1
                   FROM diskaudit.file_category_patterns fcp
                  WHERE ((fcp.category = 'cache_temp'::text) AND (f.path ~~ fcp.pattern)))) AS is_cache_temp,
            (EXISTS ( SELECT 1
                   FROM diskaudit.file_category_patterns fcp
                  WHERE ((fcp.category = 'user_data'::text) AND (f.path ~~ fcp.pattern)))) AS is_user_data
           FROM (diskaudit.files f
             LEFT JOIN diskaudit.mv_file_status mfs ON (((mfs.host = f.host) AND (mfs.path = f.path))))
          WHERE ((f.duplicate_group_id IS NOT NULL) AND f.still_exists AND (f.file_type = 'regular'::text))
        )
 SELECT duplicate_group_id,
    host,
    count(*) AS file_count,
    count(DISTINCT inode) AS distinct_inode_count,
    max(size_bytes) AS size_bytes,
    (GREATEST((count(DISTINCT inode) - 1), (0)::bigint) * max(size_bytes)) AS reclaimable_bytes,
    bool_and((content_sha256 IS NOT NULL)) AS hash_proven,
    (array_agg(path ORDER BY mtime))[1] AS sample_path,
    max(mtime) AS newest_mtime,
        CASE
            WHEN bool_or(is_decommissioned) THEN 'decommissioned'::text
            WHEN bool_or(is_load_bearing) THEN 'load_bearing'::text
            WHEN (bool_or(is_os_system_critical) OR bool_or(is_os_system_extra)) THEN 'os_system'::text
            WHEN bool_or(is_application_critical) THEN 'application'::text
            WHEN bool_or(is_cache_temp) THEN 'cache_temp'::text
            WHEN bool_or(is_user_data) THEN 'user_data'::text
            ELSE 'unknown'::text
        END AS classification,
        CASE
            WHEN (count(DISTINCT inode) = 1) THEN 4
            WHEN (bool_and((content_sha256 IS NOT NULL)) AND bool_and((dedup_tool = 'crosshost-sha256'::text))) THEN 2
            WHEN (bool_and((content_sha256 IS NOT NULL)) AND bool_and((dedup_tool = 'rdfind-parallel'::text))) THEN 3
            WHEN bool_and((content_sha256 IS NOT NULL)) THEN 3
            ELSE 7
        END AS evidence_level,
        CASE
            WHEN (count(DISTINCT inode) = 1) THEN 'same_inode'::text
            WHEN (bool_and((content_sha256 IS NOT NULL)) AND bool_and((dedup_tool = 'crosshost-sha256'::text))) THEN 'sha256_both'::text
            WHEN (bool_and((content_sha256 IS NOT NULL)) AND bool_and((dedup_tool = 'rdfind-parallel'::text))) THEN 'sha256_rdfind'::text
            WHEN bool_and((content_sha256 IS NOT NULL)) THEN 'sha256_rdfind'::text
            ELSE 'none'::text
        END AS evidence_level_label,
        CASE
            WHEN (count(DISTINCT inode) = 1) THEN 'inode-stat'::text
            WHEN bool_and((hash_source = 'nas-native'::text)) THEN 'nas-native'::text
            WHEN bool_and((hash_source = 'local'::text)) THEN 'local'::text
            WHEN bool_and((hash_source = 'trigkey-agent'::text)) THEN 'trigkey-agent'::text
            WHEN (bool_and((hash_source IS NULL)) AND bool_and((dedup_tool = 'rdfind-parallel'::text))) THEN 'rdfind-pipeline'::text
            ELSE 'mixed'::text
        END AS evidence_provenance,
    now() AS refreshed_at
   FROM members m
  GROUP BY duplicate_group_id, host
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_dedup_groups_by_host; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON MATERIALIZED VIEW diskaudit.mv_dedup_groups_by_host IS 'HavnVard UI (webapp/) read-only cache of per-(duplicate_group_id, host) dedup groups,
   with classification (os_system/application/load_bearing/cache_temp/user_data/
   decommissioned/unknown) and a 7-level evidence-strength ladder + separate provenance
   axis (see 20260725_diskaudit_dedup_classification_evidence_v1.sql). Not wired to a
   refresh timer yet -- manual: REFRESH MATERIALIZED VIEW CONCURRENTLY
   diskaudit.mv_dedup_groups_by_host;';


--
-- Name: COLUMN mv_dedup_groups_by_host.classification; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON COLUMN diskaudit.mv_dedup_groups_by_host.classification IS 'Worst-case-wins across every member file: decommissioned > load_bearing > os_system >
   application > cache_temp > user_data > unknown.';


--
-- Name: COLUMN mv_dedup_groups_by_host.evidence_level; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON COLUMN diskaudit.mv_dedup_groups_by_host.evidence_level IS '1=byte_identical (not yet available) 2=sha256_both 3=sha256_rdfind 4=same_inode (hardlink,
   0 reclaim, checked before 2/3) 5=path_size_mtime 6=size_only 7=none. Strongest to weakest.';


--
-- Name: COLUMN mv_dedup_groups_by_host.evidence_provenance; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON COLUMN diskaudit.mv_dedup_groups_by_host.evidence_provenance IS 'Who computed the evidence: nas-native (QNAP BusyBox sha256sum) / local (the local machine) /
   trigkey-agent / rdfind-pipeline (rdfind''s own local hashing, no cross-host agent) /
   inode-stat (same_inode groups -- no hash needed) / mixed (evidence_level 4 shows
   pipeline-tool disagreement -- true doubt, no rows have this today).';


