--
-- Name: v_critical_files; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_critical_files AS
 SELECT host,
    path,
    size_bytes,
    duplicate_group_id
   FROM diskaudit.files f
  WHERE (still_exists AND (file_type = 'regular'::text) AND (EXISTS ( SELECT 1
           FROM diskaudit.critical_patterns cp
          WHERE (f.path ~~ cp.pattern))));


--
-- Name: VIEW v_critical_files; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON VIEW diskaudit.v_critical_files IS 'Every live regular file matching a diskaudit.critical_patterns rule, any host. Helper view underlying diskaudit.v_backup_coverage -- can be a very large set when broad critical_patterns are seeded.';


--
-- Name: v_backup_coverage; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_backup_coverage AS
 SELECT cf.host,
    cf.path,
    cf.size_bytes,
    cf.duplicate_group_id,
    COALESCE(cov.covering_hosts, ARRAY[]::text[]) AS covering_hosts,
    ((cf.duplicate_group_id IS NOT NULL) AND (cov.covering_hosts IS NOT NULL)) AS is_backed_up
   FROM (diskaudit.v_critical_files cf
     LEFT JOIN LATERAL ( SELECT array_agg(DISTINCT g.host ORDER BY g.host) AS covering_hosts
           FROM diskaudit.files g
          WHERE ((g.duplicate_group_id = cf.duplicate_group_id) AND (g.host <> cf.host) AND g.still_exists AND (g.file_type = 'regular'::text))) cov ON ((cf.duplicate_group_id IS NOT NULL)));


--
-- Name: VIEW v_backup_coverage; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON VIEW diskaudit.v_backup_coverage IS 'One row per critical file (diskaudit.critical_patterns). is_backed_up=true iff a content-identical (same duplicate_group_id) live copy exists on >=1 OTHER host. duplicate_group_id IS NULL (never deduped) or single-host-only both report is_backed_up=false, covering_hosts=''{}'' -- conservative by design, never silently excluded. Coverage fills in as NAS crawl and dedup work lands; this is a live view, not a point-in-time report.';


--
-- Name: v_duplicate_groups_by_host; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_duplicate_groups_by_host AS
 SELECT duplicate_group_id,
    host,
    count(*) AS file_count,
    count(DISTINCT inode) AS distinct_inode_count,
    max(size_bytes) AS size_bytes,
    (GREATEST((count(DISTINCT inode) - 1), (0)::bigint) * max(size_bytes)) AS reclaimable_bytes
   FROM diskaudit.files
  WHERE ((duplicate_group_id IS NOT NULL) AND still_exists AND (file_type = 'regular'::text))
  GROUP BY duplicate_group_id, host;


--
-- Name: v_duplicate_groups; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_duplicate_groups AS
 SELECT duplicate_group_id,
    array_agg(DISTINCT host ORDER BY host) AS hosts,
    count(DISTINCT host) AS host_count,
    sum(file_count) AS total_file_count,
    max(size_bytes) AS size_bytes,
    sum(reclaimable_bytes) AS reclaimable_bytes_total
   FROM diskaudit.v_duplicate_groups_by_host
  GROUP BY duplicate_group_id;


--
-- Name: v_file_status; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_file_status AS
 SELECT host,
    path,
    file_type,
    size_bytes,
    owner_name,
    mtime,
    atime,
    duplicate_group_id,
    is_legacy_naming,
    file_status,
    is_load_bearing,
    is_decommissioned,
    is_critical,
    is_duplicated,
    is_atime_old,
    computed_at
   FROM diskaudit.mv_file_status;


--
-- Name: VIEW v_file_status; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON VIEW diskaudit.v_file_status IS 'Thin alias for diskaudit.mv_file_status (spec-literal name). Freshness = last materialized-view refresh, not query time.';


--
-- Name: v_git_tracked_recency; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_git_tracked_recency AS
 SELECT g.repo_root,
    f.host,
    count(*) AS file_count,
    sum(f.size_bytes) AS total_size_bytes,
    max(f.mtime) AS most_recent_mtime,
    max(f.atime) AS most_recent_atime,
    (now() - max(f.mtime)) AS mtime_age,
    (max(f.mtime) < (now() - '180 days'::interval)) AS looks_cold_180d
   FROM (diskaudit.git_repo_roots g
     JOIN diskaudit.files f ON ((f.still_exists AND ((f.path = g.repo_root) OR (f.path ~~ (g.repo_root || '/%'::text))))))
  GROUP BY g.repo_root, f.host;


--
-- Name: VIEW v_git_tracked_recency; Type: COMMENT; Schema: diskaudit; Owner: -
--

COMMENT ON VIEW diskaudit.v_git_tracked_recency IS 'Filesystem-mtime proxy for git-repo activity, scoped to diskaudit.git_repo_roots. NOT real git-log data. Supplementary signal only, not wired into file_status.';


--
-- Name: v_infra126_sla_status; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_infra126_sla_status AS
 SELECT host,
    tier,
    target_recheck_days,
    schedule_mode,
    last_completed_at,
    last_successful_at,
    last_completed_status,
    last_run_id,
    last_successful_run_id,
    next_scheduled_at,
    files_total,
    files_on_time,
    files_pending,
    critical_overdue_count,
    pct_on_time,
        CASE
            WHEN (files_total = 0) THEN 'NO_ELIGIBLE_FILES'::text
            WHEN (last_successful_at IS NULL) THEN 'NEVER_SUCCESSFUL'::text
            WHEN ((next_scheduled_at IS NOT NULL) AND (next_scheduled_at < now())) THEN 'OVERDUE'::text
            WHEN (last_completed_status = 'completed_with_errors'::text) THEN 'COMPLETED_WITH_ERRORS'::text
            ELSE 'ON_TIME'::text
        END AS sla_state
   FROM diskaudit.hash_verification_sla;


--
-- Name: v_infra126_verification_age; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_infra126_verification_age AS
 SELECT host,
    path,
    inode,
    (md5(((((host || '
'::text) || path) || '
'::text) || COALESCE((inode)::text, ''::text))) || md5(((((('infra126:'::text || host) || '
'::text) || path) || '
'::text) || COALESCE((inode)::text, ''::text)))) AS file_key,
    size_bytes,
    content_sha256,
    first_hash,
    first_hashed_at,
    hashed_at AS current_baseline_at,
    last_hash_attempt_at,
    last_verified_at,
    last_baseline_accepted_at,
        CASE
            WHEN (first_hashed_at IS NULL) THEN NULL::bigint
            ELSE (floor((EXTRACT(epoch FROM (now() - first_hashed_at)) / (86400)::numeric)))::bigint
        END AS days_since_first_hash,
        CASE
            WHEN (last_verified_at IS NULL) THEN NULL::bigint
            ELSE (floor((EXTRACT(epoch FROM (now() - last_verified_at)) / (86400)::numeric)))::bigint
        END AS days_since_last_verification,
    verification_count,
    baseline_revision_count,
    hash_divergence_count,
    hash_status,
    hash_error,
    hash_baseline_mtime_ns,
    hash_baseline_size,
    hash_baseline_inode,
    hash_baseline_metadata_trusted,
    (EXISTS ( SELECT 1
           FROM diskaudit.infra126_critical_files c
          WHERE ((c.host = f.host) AND (c.path = f.path)))) AS is_critical
   FROM diskaudit.files f
  WHERE (still_exists AND (file_type = 'regular'::text));


--
-- Name: v_sla_status; Type: VIEW; Schema: diskaudit; Owner: -
--

CREATE VIEW diskaudit.v_sla_status AS
 SELECT host,
    tier,
    target_recheck_days,
    schedule_mode,
    last_completed_at,
    last_successful_at,
    last_completed_status,
    last_run_id,
    last_successful_run_id,
    next_scheduled_at,
    files_total,
    files_on_time,
    files_pending,
    critical_overdue_count,
    pct_on_time,
    sla_state
   FROM diskaudit.v_infra126_sla_status;


