-- HavnVard generic starting rules. Appended to schema/baseline.sql by scripts/make_baseline_schema.py.
-- Every row is a general-purpose default (OS files, caches, transient paths, NAS system folders).
-- Add your own site's rules with plain INSERTs after install; nothing here names a host or a person.

-- Backup-coverage scope: paths that never need a backup on any host ('%').
INSERT INTO diskaudit.backup_scope_rules (host_pattern, path_pattern, category, reason, priority) VALUES
    ('%', '/usr/%',               'excluded_os', 'OS/distro package files -- reinstallable via apt, not user data', 10),
    ('%', '/snap/%',              'excluded_os', 'snap-packaged app payloads -- reinstallable via snap, not user data', 10),
    ('%', '/var/lib/snapd/%',     'excluded_os', 'snapd internal state -- regenerated by snapd, not user data', 10),
    ('%', '/var/lib/docker/%',    'excluded_os', 'Docker image/container/overlay internals -- reproducible from images/Dockerfiles, not user data', 10),
    ('%', '/boot/%',              'excluded_os', 'kernel/bootloader files -- reinstallable via kernel packages', 10),
    ('%', '/lib.usr-is-merged/%', 'excluded_os', 'usr-merge compatibility symlink tree -- OS-managed, not user data', 10),
    ('%', '/bin.usr-is-merged/%', 'excluded_os', 'usr-merge compatibility symlink tree -- OS-managed, not user data', 10),
    ('%', '/sbin.usr-is-merged/%','excluded_os', 'usr-merge compatibility symlink tree -- OS-managed, not user data', 10),
    ('%', '%/.cache/%',           'excluded_cache', 'user-level cache dir (pip/npm/huggingface/etc) -- regenerated on next use', 20),
    ('%', '%/.lmstudio/models/%', 'excluded_cache', 'LM Studio downloaded model weights -- re-downloadable', 20),
    ('%', '%/__pycache__/%',      'excluded_cache', 'Python bytecode cache -- regenerated from .py source', 20),
    ('%', '%/.venv/%',            'excluded_cache', 'Python virtualenv -- rebuildable from requirements', 20),
    ('%', '%/venv/%',             'excluded_cache', 'Python virtualenv -- rebuildable from requirements', 20),
    ('%', '%/node_modules/%',     'excluded_cache', 'npm dependency tree -- rebuildable via npm install', 20),
    ('%', '%/.npm/%',             'excluded_cache', 'npm package cache -- regenerated on next install', 20),
    ('%', '%/.cargo/registry/%',  'excluded_cache', 'Rust cargo registry cache -- regenerated on next build', 20),
    ('%', '/var/cache/%',         'excluded_cache', 'system package manager cache -- regenerated on next package operation', 20),
    ('%', '/tmp/%',               'excluded_transient', 'transient scratch space', 30),
    ('%', '/var/tmp/%',           'excluded_transient', 'transient scratch space by convention', 30),
    ('%', '/proc/%',              'excluded_transient', 'kernel virtual filesystem -- not real disk content', 30),
    ('%', '/sys/%',               'excluded_transient', 'kernel virtual filesystem -- not real disk content', 30),
    ('%', '/run/%',               'excluded_transient', 'runtime tmpfs -- rebuilt every boot', 30),
    ('%', '/cdrom/%',             'excluded_transient', 'removable/optical media mount point', 30),
    ('%', '/media/%',             'excluded_transient', 'removable media mount point', 30),
    ('%', '/mnt/%',               'excluded_transient', 'ad hoc mount point -- whatever is mounted there is backed up as its own host', 30),
    ('%', '/lost+found/%',        'excluded_other', 'fsck-recovery directory -- orphaned inodes, not meaningful user data', 40)
ON CONFLICT (host_pattern, path_pattern) DO NOTHING;

-- NAS system folders (QNAP) that dedup must treat as OS-managed, not user copies.
INSERT INTO diskaudit.critical_patterns (pattern, label, source, category) VALUES
    ('%/.qpkg/%',              'QNAP app-package install directory (QTS-managed)',       'manual', 'os_system'),
    ('%/.qsync/%',             'Qsync Central sync-client state directory (QTS-managed)', 'manual', 'os_system'),
    ('%/@Recycle/%',           'QNAP recycle bin (QTS-managed, not a raw user delete)',   'manual', 'os_system'),
    ('%/@Recently-Snapshot/%', 'QNAP snapshot cache directory (QTS-managed)',             'manual', 'os_system')
ON CONFLICT (pattern) DO NOTHING;

-- Derived/sidecar files: safe to regenerate, never the original copy.
INSERT INTO diskaudit.file_category_patterns (pattern, category, label, source) VALUES
    ('%/.streams/%',    'cache_temp', 'QNAP AFP/Time-Machine resource-fork sidecar store', 'manual'),
    ('%/Thumbs.db',     'cache_temp', 'Windows thumbnail cache', 'manual'),
    ('%/.DS_Store',     'cache_temp', 'macOS Finder metadata', 'manual'),
    ('/tmp/%',          'cache_temp', 'Unix /tmp', 'manual'),
    ('/var/tmp/%',      'cache_temp', 'Unix /var/tmp', 'manual'),
    ('%/__pycache__/%', 'cache_temp', 'Python bytecode cache (regenerable)', 'manual'),
    ('%/.cache/%',      'cache_temp', 'XDG user cache directory (regenerable)', 'manual')
ON CONFLICT (pattern, category) DO NOTHING;

INSERT INTO diskaudit.classification_config (key, value, description) VALUES
    ('stale_atime_threshold_days', '365',
     'atime age (days) beyond which a file is a possibly-obsolete/stale candidate, subject to the load-bearing/decommissioned/critical overrides. Operator-editable; re-read on every classification refresh.')
ON CONFLICT (key) DO NOTHING;

-- Bit-rot verification (infra126): which changed files are expected to change (mutable) and which must never
-- change without an alarm (immutable). Applies to every host ('*').
INSERT INTO diskaudit.mutable_file_registry(host,path_pattern,score,reason,is_regex,pattern_kind,priority)
VALUES
('*','^/var/log/',99,'system logs',true,'mutable',10),
('*','^/var/tmp/',97,'temporary files',true,'mutable',10),
('*','^/tmp/',97,'temporary files',true,'mutable',10),
('*','*.sqlite',98,'SQLite database',false,'mutable',20),
('*','*.sqlite3',98,'SQLite database',false,'mutable',20),
('*','*.db',98,'database file',false,'mutable',30),
('*','*.db-wal',99,'SQLite WAL',false,'mutable',20),
('*','*.db-shm',99,'SQLite shared memory',false,'mutable',20),
('*','/\.config/(google-chrome|chromium)/',96,'browser profile',true,'mutable',20),
('*','/\.cache/',96,'user cache',true,'mutable',30),
('*','/\.git/',95,'Git metadata',true,'mutable',30),
('*','^/run/',99,'runtime state',true,'mutable',10),
('*','^/var/run/',99,'runtime state',true,'mutable',10),
('*','^/var/lib/docker/',95,'container runtime data',true,'mutable',40),
('*','^/var/lib/postgresql/',99,'PostgreSQL data directory',true,'mutable',10),
('*','^/etc/hostname$',10,'host identity',true,'immutable',1),
('*','^/etc/(passwd|group|shadow|gshadow)$',15,'account database',true,'immutable',1),
('*','^/etc/(fstab|crypttab)$',10,'storage boot configuration',true,'immutable',1),
('*','^/boot/',10,'boot files',true,'immutable',1),
('*','^/(usr/)?(bin|sbin)/',10,'system executable',true,'immutable',2),
('*','^/(usr/)?lib/',10,'system library',true,'immutable',2),
('*','^/etc/systemd/system/',10,'systemd unit',true,'immutable',1),
('*','^/etc/cron',10,'scheduler configuration',true,'immutable',1)
ON CONFLICT(host,path_pattern,reason) DO UPDATE
SET score=EXCLUDED.score,is_regex=EXCLUDED.is_regex,
    pattern_kind=EXCLUDED.pattern_kind,priority=EXCLUDED.priority;

